glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1.0);
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant {
  vec4 tint;
  vec4 params;
};
#define TAU 6.28318530718
float hash21(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
vec3 dustLayer(vec2 uv, float scale, float t, float yOff, float seed){
  vec2 suv = vec2(uv.x, uv.y * 1.779);
  suv.y -= t * params.x * yOff;
  suv.x += sin(t * 0.3 + suv.y * 3.0) * params.w * 0.03;
  vec2 p = suv * scale;
  vec2 cell = floor(p + seed);
  vec2 f = fract(p + seed) - 0.5;
  float h = hash21(cell);
  float present = step(0.78, h) * params.y;
  vec2 sp = (vec2(hash21(cell + 11.3), hash21(cell + 21.7)) - 0.5) * 0.6;
  float r = length(f - sp);
  float core = smoothstep(0.10, 0.0, r);
  float tw = 0.4 + 0.6 * sin(t * (1.8 + 2.0 * hash21(cell + 3.3)) + h * TAU);
  return tint.rgb * core * present * mix(0.4, 1.0, tw * params.z);
}
vec4 frag () {
  vec2 uv = uv0;
  float t = cc_time.x;
  vec3 col = dustLayer(uv, 30.0, t, 1.00, 0.0)
           + dustLayer(uv, 55.0, t, 1.35, 3.1) * 0.7
           + dustLayer(uv, 90.0, t, 1.70, 7.9) * 0.45;
  col *= smoothstep(1.0, 0.6, uv.y);
  float a = clamp(max(col.r, max(col.g, col.b)) * 1.4, 0.0, 1.0);
  return vec4(col, a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

